'use strict'

const SOURCES = new Set(['gmail', 'drive', 'calendar', 'github'])
const MAX_FOLLOWUP_SOURCES = 2

// One bounded continuation of the judged plan, never a plan generated by source
// content. Missing evidence is a reason to look, not authority or proof of absence.
function planFollowupReads (report, plan, authorised, attempted = []) {
  const allow = new Set(authorised || [])
  const seen = new Set([...attempted, ...(report?.crossSourceReads || []).map(r => r.source)])
  const gaps = (report?.gaps || []).map(g => g.section).filter(Boolean)
  const insufficient = report?.state === 'unavailable' || gaps.length > 0 ||
    report?.contradictions?.length > 0
  const result = { version: 1, maxSources: MAX_FOLLOWUP_SOURCES, rounds: 1,
    trigger: insufficient ? 'evidence_gap' : 'no_reported_gap', gapSections: [...new Set(gaps)],
    sources: [], decisions: [] }
  if (report?.readOnly !== true) return { ...result, trigger: 'outside_read_only_investigation' }
  const considered = new Set()
  for (const fact of plan?.facts || []) {
    if (fact?.necessity !== 'enriching' || !SOURCES.has(fact.operation) || considered.has(fact.operation)) continue
    const source = fact.operation
    considered.add(source)
    const reason = !allow.has(source) ? 'not_authorized' : seen.has(source) ? 'already_attempted'
      : !insufficient ? 'no_reported_gap' : result.sources.length >= MAX_FOLLOWUP_SOURCES ? 'source_limit' : 'selected'
    result.decisions.push({ source, reason })
    if (reason === 'selected') result.sources.push(source)
  }
  return result
}

function renderFollowupReads (followup, message = '') {
  if (!followup?.decisions?.length) return null
  const zh = /[\u3400-\u9fff]/.test(message)
  const labels = zh
    ? { sampled: '已補查，僅為取樣', empty: '已補查，搜尋無命中', unavailable: '補查未能讀取', not_authorized: '未獲授權，本次未查', already_attempted: '本回合已查，不重複讀取', no_reported_gap: '沒有記錄到需補查的缺口', source_limit: '已達本輪補查上限，未查' }
    : { sampled: 'sampled in follow-up', empty: 'follow-up search had no matches', unavailable: 'follow-up read unavailable', not_authorized: 'not authorized; not read', already_attempted: 'already attempted this turn; not repeated', no_reported_gap: 'no reported gap requiring follow-up', source_limit: 'follow-up limit reached; not read' }
  return (zh ? '補查紀錄：' : 'Follow-up reads: ') + followup.decisions.map(d =>
    d.source + ' — ' + (labels[d.state || d.reason] || (zh ? '尚未取得結果' : 'no result yet'))).join('；') +
    (zh ? '。未命中不代表其他紀錄不存在，補查也不代表原有證據缺口已解決。' : '. No matches do not establish global absence, and follow-up does not by itself resolve the original evidence gaps.')
}

module.exports = { planFollowupReads, renderFollowupReads }
